class DuplicatedCheckpointIDs(Exception):
    """
    Raised when checkpoints IDs in diagnostic check report are duplicated.
    """
    pass


class CheckpointsVerificationError(Exception):
    """
    Raised when checkpoints verification in diagnostic check report failed.
    """
    pass


class CheckpointKeyError(Exception):
    """
    Raised when checkpoint key name is not found.
    """
    pass
